// Core tests: the 9 literal core cases from the fixed spec's fixtures.json
// (vendored verbatim at test/fixtures.json from spec candidate
// ea00dfbb1d076eb3eedd47e1f3d4afae204d578d; expected values taken verbatim,
// never generated by the product), plus hand-derived boundary, rounding,
// and validation-order cases. The SPEC's own rules are the oracle; every
// extra expected value below was computed by hand from those rules.

import assert from "node:assert/strict";
import test from "node:test";
import { formatAmount, formatRatioLabel, run } from "../public/js/core/brew.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("every fixture success ends exactly at the total water", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const { result } = entry.expected;
    assert.equal(result.steps.length, 4, entry.id);
    assert.deepEqual(
      result.steps.map((step) => step.kind),
      ["bloom", "pour", "pour", "pour"],
      entry.id,
    );
    assert.equal(result.steps[3].cumulativeMl, result.totalWaterMl, entry.id);
    const added = result.steps.reduce((sum, step) => sum + Math.round(step.addMl * 10), 0);
    assert.equal(added, Math.round(result.totalWaterMl * 10), entry.id);
  }
});

// Hand-derived: dose 15 g, ratio 1:14, bloom 2.
// W = floor((150*140+5)/10) = 2100; B = floor((150*20+5)/10) = 300;
// S = 1800, base 600, remainder 0 -> three pours of 60.0.
test("hand-derived dose case with remainder 0", () => {
  assert.deepEqual(run({ mode: "dose", amount: "15", ratio: "14", bloomMultiplier: "2" }), {
    ok: true,
    result: {
      mode: "dose",
      doseGrams: 15,
      totalWaterMl: 210,
      ratio: 14,
      bloomMultiplier: 2,
      bloomWaterMl: 30,
      steps: [
        { step: 1, kind: "bloom", addMl: 30, cumulativeMl: 30 },
        { step: 2, kind: "pour", addMl: 60, cumulativeMl: 90 },
        { step: 3, kind: "pour", addMl: 60, cumulativeMl: 150 },
        { step: 4, kind: "pour", addMl: 60, cumulativeMl: 210 },
      ],
    },
  });
});

// Hand-derived: water 1000 ml, ratio 1:12.5, bloom 3.
// D = floor((20*10000+125)/(2*125)) = floor(200125/250) = 800;
// B = floor((800*30+5)/10) = 2400; S = 7600, base 2533, remainder 1 ->
// pours 253.4, 253.3, 253.3.
test("hand-derived water case with a custom ratio and remainder 1", () => {
  assert.deepEqual(run({ mode: "water", amount: "1000", ratio: "12.5", bloomMultiplier: "3" }), {
    ok: true,
    result: {
      mode: "water",
      doseGrams: 80,
      totalWaterMl: 1000,
      ratio: 12.5,
      bloomMultiplier: 3,
      bloomWaterMl: 240,
      steps: [
        { step: 1, kind: "bloom", addMl: 240, cumulativeMl: 240 },
        { step: 2, kind: "pour", addMl: 253.4, cumulativeMl: 493.4 },
        { step: 3, kind: "pour", addMl: 253.3, cumulativeMl: 746.7 },
        { step: 4, kind: "pour", addMl: 253.3, cumulativeMl: 1000 },
      ],
    },
  });
});

// Hand-derived: water 25 ml at ratio 1:20 solves to exactly 1.25 g, which
// half-up rounds to 1.3. D = floor((20*250+200)/(2*200)) = floor(5200/400)
// = 13; B = floor((13*20+5)/10) = 26; S = 224, base 74, remainder 2 ->
// pours 7.5, 7.5, 7.4.
test("water mode rounds an exact .5 dose up", () => {
  assert.deepEqual(run({ mode: "water", amount: "25", ratio: "20", bloomMultiplier: "2" }), {
    ok: true,
    result: {
      mode: "water",
      doseGrams: 1.3,
      totalWaterMl: 25,
      ratio: 20,
      bloomMultiplier: 2,
      bloomWaterMl: 2.6,
      steps: [
        { step: 1, kind: "bloom", addMl: 2.6, cumulativeMl: 2.6 },
        { step: 2, kind: "pour", addMl: 7.5, cumulativeMl: 10.1 },
        { step: 3, kind: "pour", addMl: 7.5, cumulativeMl: 17.6 },
        { step: 4, kind: "pour", addMl: 7.4, cumulativeMl: 25 },
      ],
    },
  });
});

// Hand-derived minimum edges: dose 1 g, ratio 1:10, bloom 0.
// W = floor((10*100+5)/10) = 100; B = 0; S = 100, base 33, remainder 1.
test("minimum dose, minimum ratio, zero bloom", () => {
  assert.deepEqual(run({ mode: "dose", amount: "1", ratio: "10", bloomMultiplier: "0" }), {
    ok: true,
    result: {
      mode: "dose",
      doseGrams: 1,
      totalWaterMl: 10,
      ratio: 10,
      bloomMultiplier: 0,
      bloomWaterMl: 0,
      steps: [
        { step: 1, kind: "bloom", addMl: 0, cumulativeMl: 0 },
        { step: 2, kind: "pour", addMl: 3.4, cumulativeMl: 3.4 },
        { step: 3, kind: "pour", addMl: 3.3, cumulativeMl: 6.7 },
        { step: 4, kind: "pour", addMl: 3.3, cumulativeMl: 10 },
      ],
    },
  });
});

const valid = { mode: "dose", amount: "20", ratio: "15", bloomMultiplier: "2" };
const errorOf = (input) => run(input).error;

test("SCHEMA: non-objects, arrays, missing, extra, wrong types, accessors", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("dose"), schema);
  assert.deepEqual(errorOf(["dose", "20", "15", "2"]), schema);
  assert.deepEqual(errorOf({ mode: "dose", amount: "20", ratio: "15" }), schema);
  assert.deepEqual(errorOf({ ...valid, extra: "1" }), schema);
  assert.deepEqual(errorOf({ ...valid, amount: 20 }), schema);
  assert.deepEqual(errorOf({ ...valid, mode: true }), schema);
  const withAccessor = { mode: "dose", ratio: "15", bloomMultiplier: "2" };
  Object.defineProperty(withAccessor, "amount", {
    enumerable: true,
    get() {
      return "20";
    },
  });
  assert.deepEqual(errorOf(withAccessor), schema);
});

test("validation order: mode first, then amount, ratio, bloomMultiplier", () => {
  assert.deepEqual(errorOf({ mode: "both", amount: "250", ratio: "25", bloomMultiplier: "9" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ mode: "dose", amount: "1.25", ratio: "25", bloomMultiplier: "9" }), {
    code: "DECIMAL_FORMAT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ mode: "dose", amount: "20", ratio: "25", bloomMultiplier: "9" }), {
    code: "RANGE",
    field: "ratio",
    row: null,
  });
});

test("per-field order: capacity before unicode before empty before grammar", () => {
  assert.deepEqual(errorOf({ ...valid, amount: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, amount: "12345678\uD800" }), {
    code: "INPUT_LIMIT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, ratio: "1\uD800" }), {
    code: "UNICODE",
    field: "ratio",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, bloomMultiplier: "" }), {
    code: "EMPTY",
    field: "bloomMultiplier",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, mode: "" }), {
    code: "EMPTY",
    field: "mode",
    row: null,
  });
});

test("decimal grammar rejects signs, spaces, leading zeros, stray dots", () => {
  for (const bad of ["015", "15.", ".5", " 15", "15 ", "+15", "-15", "1,5", "1e3", "2.55"]) {
    assert.deepEqual(
      errorOf({ ...valid, ratio: bad }),
      { code: "DECIMAL_FORMAT", field: "ratio", row: null },
      `ratio ${JSON.stringify(bad)}`,
    );
  }
});

test("range edges just outside each bound", () => {
  assert.deepEqual(errorOf({ ...valid, amount: "0.9" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, amount: "200.1" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, mode: "water", amount: "9.9" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, mode: "water", amount: "4000.1" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, ratio: "9.9" }), {
    code: "RANGE",
    field: "ratio",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, ratio: "20.1" }), {
    code: "RANGE",
    field: "ratio",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, bloomMultiplier: "5.1" }), {
    code: "RANGE",
    field: "bloomMultiplier",
    row: null,
  });
});

test("display formatting: one decimal always, ratio drops a trailing .0", () => {
  assert.equal(formatAmount(20), "20.0");
  assert.equal(formatAmount(86.7), "86.7");
  assert.equal(formatAmount(0), "0.0");
  assert.equal(formatAmount(2000), "2000.0");
  assert.equal(formatRatioLabel(15), "1:15");
  assert.equal(formatRatioLabel(15.5), "1:15.5");
  assert.equal(formatRatioLabel(10), "1:10");
});
